import { formatErrorDiagnostic } from "../utils/error_diagnostic";
/** Choose agent audit when available, otherwise render deterministic findings. */
import type { ResolvedAuditConfig } from "../runtime/config/contracts";
import type { BuildDebugSummaryInput } from "./contracts";
import { buildFallbackSummary } from "./fallback_summary_renderer";
import { buildDebugSummaryWithAgents } from "./pipeline";

/** 生成调试总结；AI 审计不可用时回退到确定性摘要。 */
export async function buildDebugSummaryMarkdown(
  input: BuildDebugSummaryInput,
  audit: ResolvedAuditConfig | null,
): Promise<string> {
  // 无结构化 report 时走确定性汇总，避免 LLM 在低证据条件下产生误报。
  if (input.reports.length === 0) {
    return buildFallbackSummary(input);
  }

  if (input.sessionDir && input.logicOps && input.playerViews) {
    try {
      const pipeline = await buildDebugSummaryWithAgents(
        {
          locale: input.locale,
          displayLocale: input.displayLocale,
          manifest: input.manifest,
          reports: input.reports,
          publicEvents: input.publicEvents ?? [],
          logicOps: input.logicOps,
          playerViews: input.playerViews,
          sessionDir: input.sessionDir,
        },
        audit,
      );
      if (pipeline?.markdown) {
        return pipeline.markdown;
      }
    } catch (error) {
      console.warn(
        `[debug_summary] pipeline_failed session_id=${input.manifest.session_id} error=${formatErrorDiagnostic(error, input.displayLocale ?? input.locale ?? "zh-CN")}`,
      );
    }
  }
  return buildFallbackSummary(input);
}

/** Deterministic observations and report screening for one recorded game. */
import type {
  ReplayDebugReport,
  ReplayPlayerView,
  ReplayPublicEvent,
} from "../recording/contracts";
import type { BuildDebugSummaryInput, DeterministicFinding, SummaryObservation } from "./contracts";

/** Exact historic labels; do not infer IDs from arbitrary player text. */
const REQUEST_PHASE_ALIASES: Record<string, readonly string[]> = {
  night: ["夜晚", "Night"],
  day: ["白天", "Day"],
  voting: ["投票", "Voting"],
  game_over: ["终局", "Game over"],
};
function requestPhaseMatchesTimelinePhase(requestPhase: string, timelinePhase: string): boolean {
  return (
    Object.hasOwn(REQUEST_PHASE_ALIASES, requestPhase) &&
    (requestPhase === timelinePhase || REQUEST_PHASE_ALIASES[requestPhase].includes(timelinePhase))
  );
}

export function collectObservations(input: BuildDebugSummaryInput): SummaryObservation[] {
  const events = input.publicEvents ?? [];
  const ops = input.logicOps ?? [];
  const views = input.playerViews ?? [];
  const observations: SummaryObservation[] = [];

  const timelineEntries = views.reduce((acc, view) => acc + view.timeline.length, 0);
  const selfDestructCount = events.filter(
    (e) => e.type === "wolf_self_destruct" || e.type === "white_wolf_king_self_destruct",
  ).length;
  const deathShotCount = events.filter(
    (e) =>
      e.type === "player_shot" ||
      e.type === "hunter_shot" ||
      e.type === "wolf_king_shot" ||
      e.type === "mechanical_shot",
  ).length;
  const nightResolvedCount = events.filter((e) => e.type === "night_resolved").length;

  const mismatchSeqs: number[] = [];
  const invalidDaySeqs: number[] = [];
  let fallbackCount = 0;
  let toolRejectedCount = 0;
  for (const view of views) {
    for (const entry of view.timeline) {
      if (entry.kind !== "turn") {
        continue;
      }
      if (typeof entry.day !== "number" || entry.day <= 0) {
        invalidDaySeqs.push(entry.seq);
      }
      const requestId = String(entry.request_id ?? "");
      const match = requestId.match(/^(\d+)-([a-z_]+)-/i);
      if (match) {
        const reqDay = Number(match[1]);
        const reqPhase = match[2];
        if (reqDay !== entry.day || !requestPhaseMatchesTimelinePhase(reqPhase, entry.phase)) {
          mismatchSeqs.push(entry.seq);
        }
      }
      if (entry.delta_messages.some((item) => item.kind === "fallback")) {
        fallbackCount += 1;
      }
      if (
        entry.delta_messages.some(
          (item) => item.kind === "constraint_warning" || item.kind === "retry_prompt",
        )
      ) {
        toolRejectedCount += 1;
      }
      if (
        entry.delta_messages.some((item) => item.kind === "tool_call" && item.accepted === false)
      ) {
        toolRejectedCount += 1;
      }
    }
  }

  observations.push({
    code: "event_counts",
    title: "audit.observation.event_counts.title",
    detail: {
      key: "audit.observation.event_counts.detail",
      parameters: {
        events: events.length,
        ops: ops.length,
        players: views.length,
        timeline: timelineEntries,
      },
    },
  });
  observations.push({
    code: "process_counts",
    title: "audit.observation.process_counts.title",
    detail: {
      key: "audit.observation.process_counts.detail",
      parameters: { night: nightResolvedCount, blast: selfDestructCount, shot: deathShotCount },
    },
  });
  observations.push({
    code: "actions",
    title: "audit.observation.actions.title",
    detail: {
      key: "audit.observation.actions.detail",
      parameters: { rejected: toolRejectedCount, fallback: fallbackCount },
    },
  });

  if (invalidDaySeqs.length > 0) {
    observations.push({
      code: "invalid_day",
      title: "audit.observation.invalid_day.title",
      detail: {
        key: "audit.observation.invalid_day.detail",
        parameters: { count: invalidDaySeqs.length },
      },
      evidence: invalidDaySeqs.slice(0, 10),
    });
  }
  if (mismatchSeqs.length > 0) {
    observations.push({
      code: "request_mismatch",
      title: "audit.observation.request_mismatch.title",
      detail: {
        key: "audit.observation.request_mismatch.detail",
        parameters: { count: mismatchSeqs.length },
      },
      evidence: mismatchSeqs.slice(0, 10),
    });
  }

  return observations;
}
export function filterActionableReports(
  reports: ReplayDebugReport[],
  publicEvents: ReplayPublicEvent[],
): ReplayDebugReport[] {
  return reports.filter((report) => isActionableReport(report, publicEvents));
}

function isActionableReport(report: ReplayDebugReport, publicEvents: ReplayPublicEvent[]): boolean {
  const message = report.message;
  const category = report.category;
  const text = String(message ?? "").trim();
  if (!text) {
    return false;
  }
  const hasEvidenceSeq =
    Array.isArray(report.evidence_event_seq) && report.evidence_event_seq.length > 0;

  const hardBugSignal =
    /(日志|广播|顺序|重复|缺失|未(触发|执行|生效|公布|记录|结算)|跳过|死后|出局后|仍然发言|工具.*调用|调用.*失败|报错|error|timeout|fallback|不一致|矛盾|\bcontradict(?:ion|s|ory)?\b|越权|空守|弃票|\blogs?\b|\bbroadcast\b|\border\b|\bduplicate\b|\bmissing\b|\bskipped\b|\bafter death\b|\bafter elimination\b|\btool.*call\b|\bcall.*failed\b|\binconsistent\b|\bunauthorized\b|\babstain\b|没(有)?(公布|记录|触发|执行|生效))/i;
  if (hardBugSignal.test(text) && (hasEvidenceSeq || detectFlowAnomaly(publicEvents))) {
    return true;
  }

  const strategyNoise =
    /(狼队|队友|悍跳|金水|查验|站边|刀口|带队|配合|盘逻辑|好人阵营|狼人阵营|局势对.*(有利|不利)|报假查验|\b(?:wolf team|teammates?|bluff|role claim|inspection|alignment|good team|werewolf team|kill target|favorable|unfavorable)\b)/i;
  if (strategyNoise.test(text)) {
    return false;
  }

  const softActionableSignal =
    /(流程|阶段|票型|投票|放逐|遗言|警长|上警|退水|\b(?:flow|phase|stage|votes?|voting|exile|last words|sheriff|nomination|withdrawal)\b)/i;
  if (softActionableSignal.test(text)) {
    return (
      hasEvidenceSeq ||
      ((category === "flow" || category === "rule" || category === "logging") &&
        detectFlowAnomaly(publicEvents))
    );
  }

  // 规则/流程类分类在无明显噪声时默认保留，避免漏掉简短上报。
  return hasEvidenceSeq && (category === "flow" || category === "rule" || category === "logging");
}

function detectFlowAnomaly(events: ReplayPublicEvent[]): boolean {
  if (events.length === 0) {
    return false;
  }
  const phaseChanged = events.filter((e) => e.type === "phase_changed");
  const allowed = new Set([
    "night->day:0",
    "day->voting:0",
    "day->night:1",
    "voting->night:1",
    "night->game_over:0",
    "day->game_over:0",
    "voting->game_over:0",
  ]);
  for (let i = 1; i < phaseChanged.length; i++) {
    const prev = phaseChanged[i - 1];
    const curr = phaseChanged[i];
    const key = `${String(prev.payload.phase ?? prev.phase)}->${String(curr.payload.phase ?? curr.phase)}:${Number(curr.day) - Number(prev.day)}`;
    if (!allowed.has(key)) {
      return true;
    }
  }

  const firstDaySpeechByDay = new Map<number, number>();
  const nightResolvedByDay = new Set<number>();
  for (const e of events) {
    if (e.type === "night_resolved") {
      nightResolvedByDay.add(Number(e.day));
    }
    if (e.type === "day_speech" && !firstDaySpeechByDay.has(Number(e.day))) {
      firstDaySpeechByDay.set(Number(e.day), Number(e.seq));
    }
  }
  for (const [day] of firstDaySpeechByDay.entries()) {
    if (day <= 1) {
      continue;
    }
    if (!nightResolvedByDay.has(day)) {
      return true;
    }
  }
  return false;
}

export function scanEventsForPotentialIssues(
  input: BuildDebugSummaryInput,
): DeterministicFinding[] {
  const events = input.publicEvents ?? [];
  const findings: DeterministicFinding[] = [];

  const selfDestruct = events.filter(
    (e) => e.type === "wolf_self_destruct" || e.type === "white_wolf_king_self_destruct",
  );
  for (const e of selfDestruct) {
    if (e.day === 1) {
      findings.push({
        severity: "medium",
        category: "rule",
        day: e.day,
        phase: e.phase,
        actorId: Number((e.payload as any).wolfId ?? (e.payload as any).actorId ?? 0),
        code: "first_day_blast",
        message: { key: "audit.check.first_day_blast" },
        evidence: [e.seq],
      });
    }
  }

  const hasGuardRole = input.manifest.players.some((p) => p.role === "guard");
  if (!hasGuardRole) {
    const guardMentions = events.filter(
      (e) =>
        (e.type === "day_speech" || e.type === "last_words_spoken") &&
        /(守卫|\bguard\b)/i.test(String((e.payload as any).text ?? "")),
    );
    if (guardMentions.length > 0) {
      findings.push({
        severity: "low",
        category: "state",
        day: guardMentions[0].day,
        phase: guardMentions[0].phase,
        actorId: Number(
          (guardMentions[0].payload as any).actorId ??
            (guardMentions[0].payload as any).playerId ??
            0,
        ),
        code: "guard_mention",
        message: { key: "audit.check.guard_mention" },
        evidence: guardMentions.slice(0, 6).map((e) => e.seq),
      });
    }
  }

  const witchId = input.manifest.players.find((p) => p.role === "witch")?.player_id ?? 0;
  if (witchId > 0) {
    const usedPotion = events.some((e) => e.type === "witch_potion_used");
    const witchSpeechClaims = events.filter(
      (e) =>
        (e.type === "day_speech" || e.type === "last_words_spoken") &&
        Number((e.payload as any).actorId ?? (e.payload as any).playerId ?? -1) === witchId &&
        /(用了救药|用了毒药|使用了?解药|使用了?毒药|\b(?:used|have used|administered)\s+(?:the\s+|my\s+|an?\s+)?(?:antidote|poison|healing potion|poison potion)\b)/i.test(
          String((e.payload as any).text ?? ""),
        ),
    );
    if (!usedPotion && witchSpeechClaims.length > 0) {
      findings.push({
        severity: "medium",
        category: "logging",
        day: witchSpeechClaims[0].day,
        phase: witchSpeechClaims[0].phase,
        actorId: witchId,
        code: "potion_claim",
        message: { key: "audit.check.potion_claim" },
        evidence: witchSpeechClaims.slice(0, 6).map((e) => e.seq),
      });
    }
  }

  return findings;
}

export function scanPlayerTimelineMetadataIssues(
  views: ReplayPlayerView[],
): DeterministicFinding[] {
  const findings: DeterministicFinding[] = [];

  for (const view of views) {
    const invalidDaySeqs: number[] = [];
    const inconsistentReqSeqs: number[] = [];

    for (const entry of view.timeline) {
      if (entry.kind !== "turn") {
        continue;
      }

      if (typeof entry.day !== "number" || entry.day <= 0) {
        invalidDaySeqs.push(entry.seq);
      }

      const requestId = String(entry.request_id ?? "");
      const match = requestId.match(/^(\d+)-([a-z_]+)-/i);
      if (!match) {
        continue;
      }
      const reqDay = Number(match[1]);
      const reqPhase = match[2];
      if (reqDay !== entry.day || !requestPhaseMatchesTimelinePhase(reqPhase, entry.phase)) {
        inconsistentReqSeqs.push(entry.seq);
      }
    }

    if (invalidDaySeqs.length > 0) {
      findings.push({
        severity: "high",
        category: "logging",
        day: 0,
        phase: "unknown",
        actorId: view.player_id,
        code: "invalid_day",
        message: { key: "audit.check.invalid_day" },
        evidence: invalidDaySeqs.slice(0, 8),
      });
    }

    if (inconsistentReqSeqs.length > 0) {
      findings.push({
        severity: "medium",
        category: "logging",
        day: 0,
        phase: "unknown",
        actorId: view.player_id,
        code: "request_mismatch",
        message: { key: "audit.check.request_mismatch" },
        evidence: inconsistentReqSeqs.slice(0, 8),
      });
    }
  }

  return findings;
}

import { auditHeadings, renderMessage, text, type MessageKey } from "@ai-werewolf-arena/game-text";
import { auditInline, auditSummaryHeader } from "./summary_format";
/** Render a deterministic summary when AI audit is unavailable or unnecessary. */
import type { ReplayDebugReport } from "../recording/contracts";
import type { BuildDebugSummaryInput } from "./contracts";
import {
  collectObservations,
  filterActionableReports,
  scanEventsForPotentialIssues,
  scanPlayerTimelineMetadataIssues,
} from "./deterministic_checks";

export function buildFallbackSummary(input: BuildDebugSummaryInput): string {
  const { manifest, reports } = input;
  const locale = input.displayLocale ?? input.locale ?? "zh-CN";
  const headings = auditHeadings(locale);
  const actionableReports = filterActionableReports(reports, input.publicEvents ?? []);
  const autoFindings = scanEventsForPotentialIssues(input);
  const metadataFindings = scanPlayerTimelineMetadataIssues(input.playerViews ?? []);
  const allFindings = [
    ...actionableReports.map((r) => ({
      severity: r.severity,
      category: r.category,
      day: r.day,
      phase: r.phase,
      actorId: r.actor_id,
      message: r.message,
      evidence: Array.isArray(r.evidence_event_seq) ? r.evidence_event_seq : [],
    })),
    ...[...autoFindings, ...metadataFindings].map((item) => ({
      ...item,
      message: renderMessage(locale, item.message),
    })),
  ];
  const observations = collectObservations(input);
  const lines = auditSummaryHeader(manifest, reports, locale, actionableReports.length);

  if (allFindings.length === 0) {
    lines.push(`- ${text(locale, "common.none")}`);
  } else {
    for (const report of allFindings) {
      const evidence = report.evidence.length > 0 ? ` evidence=${report.evidence.join(",")}` : "";
      lines.push(
        `- [${report.severity.toUpperCase()}][${auditInline(report.category)}] day=${report.day} phase=${auditInline(report.phase)} actor=${report.actorId}: ${auditInline(report.message)}${evidence}`,
      );
    }
  }

  lines.push("", `## ${headings.observations}`);
  if (observations.length === 0) {
    lines.push(`- ${text(locale, "common.none")}`);
  } else {
    for (const obs of observations) {
      const evidence =
        obs.evidence && obs.evidence.length > 0 ? ` evidence=${obs.evidence.join(",")}` : "";
      lines.push(`- ${text(locale, obs.title)}: ${renderMessage(locale, obs.detail)}${evidence}`);
    }
  }

  lines.push("", `## ${headings.todo}`);
  if (allFindings.length > 0) {
    allFindings
      .slice()
      .sort((a, b) => {
        const rank = { critical: 4, high: 3, medium: 2, low: 1 } as const;
        return rank[b.severity] - rank[a.severity];
      })
      .forEach((report, idx) => {
        lines.push(
          `- [ ] [P${idx + 1}] ${text(locale, "audit.todo", { category: text(locale, `audit.category.${report.category}` as MessageKey), message: auditInline(report.message) })} (actor=${report.actorId}, day=${report.day}, phase=${auditInline(report.phase)})`,
        );
      });
  } else {
    // 批量运行场景：无问题时避免输出待办噪声，给出明确“无需处理”结论。
    lines.pop(); // remove "## TODO"
    lines.push("", `## ${headings.conclusion}`, `- ${text(locale, "audit.conclusion")}`);
  }

  lines.push("", `## ${headings.pipeline}`, `- ${text(locale, "audit.pipeline.fallback")}`);
  return lines.join("\n");
}

import { assertReplayDocument, REPLAY_SCHEMA_VERSION } from "@ai-werewolf-arena/replay-contract";
import type { ReplayDocument } from "@ai-werewolf-arena/replay-contract";
import { ReplayManifest, ReplayPublicEvent } from "./contracts";

/** 浏览器播放器与视频渲染器直接消费的离线复盘文件。 */
export type { ReplayDocument } from "@ai-werewolf-arena/replay-contract";

/**
 * 从 record 的规范数据构造前端投影。
 *
 * events 不做筛选、合并或重排，确保领域事件无丢失；派生的阶段窗口、
 * 最终存活状态及 Agent 审计轨迹不重复写入前端文件。
 */
export function createReplayDocument(input: {
  manifest: ReplayManifest;
  events: ReplayPublicEvent[];
}): ReplayDocument {
  assertCanonicalEventSequence(input.events);
  assertUniquePlayers(input.manifest.players);

  const document: ReplayDocument = {
    schemaVersion: REPLAY_SCHEMA_VERSION,
    perspective: "god",
    sessionId: input.manifest.session_id,
    meta: {
      board: input.manifest.board,
      ...(input.manifest.locale === undefined ? {} : { locale: input.manifest.locale }),
      startedAt: input.manifest.started_at,
      endedAt: input.manifest.ended_at,
    },
    result: {
      winner: input.manifest.winner,
      reason: input.manifest.finish_reason || null,
      ...(input.manifest.game_result
        ? { decision: structuredClone(input.manifest.game_result) }
        : {}),
    },
    players: input.manifest.players.map(({ player_id, role, camp, name }) => ({
      player_id,
      role,
      camp,
      ...(name !== undefined ? { name } : {}),
    })),
    events: input.events,
  };
  assertReplayDocument(document);
  return document;
}

function assertCanonicalEventSequence(events: ReplayPublicEvent[]): void {
  for (let index = 0; index < events.length; index += 1) {
    if (events[index].seq !== index + 1) {
      throw new Error(
        `replay_document_non_canonical_event_sequence:index=${index},seq=${events[index].seq}`,
      );
    }
  }
}

function assertUniquePlayers(players: ReplayManifest["players"]): void {
  const ids = new Set<number>();
  for (const player of players) {
    if (ids.has(player.player_id)) {
      throw new Error(`replay_document_duplicate_player:${player.player_id}`);
    }
    ids.add(player.player_id);
  }
}

/**
 * 负责单会话事件、玩家回合与诊断的原内存聚合；输入为录制数据，输出为原公开／玩家 schema 2 快照与清单。
 * 本 owner 保留局部序号、原文、初始prompt和操作计数；写盘格式声明由 manager／档案 codec 拥有。
 * 玩家规范化已在原返回前调用完整断言，故返回类型明确为 canonical2；不改变字段、IO或资源／游戏状态。
 */
import { assertReplayPlayerView, readVictoryResult, type CanonicalReplayPlayerView } from "@ai-werewolf-arena/replay-contract";
import { PlayerVisibleEvent } from "../core/domain/model";
import {
  ReplayDebugReport,
  ReplayFinalizeMeta,
  ReplayLlmRequestMessage,
  ReplayLogicOp,
  ReplayManifest,
  ReplayPhaseWindow,
  ReplayPhaseWindowsFile,
  ReplayPlayerDeltaMessage,
  ReplayPlayerEventEntry,
  ReplayPlayerView,
  ReplayPublicEvent,
  ReplayRecordDebugReportInput,
  ReplayRecordLogicOpInput,
  ReplayRecordPlayerEventInput,
  ReplayRecordPlayerRoundInput,
  ReplayRecordPublicEventInput,
  ReplaySessionMeta,
  ReplayTimelineIndexFile,
} from "./contracts";

const THINKING_MAX_CHARS = 4000;
const LLM_MESSAGE_MAX_CHARS = 8000;

function toIso(timestampMs: number): string {
  return new Date(timestampMs).toISOString();
}

export function safeReplayJson(value: unknown): unknown {
  try {
    return JSON.parse(JSON.stringify(value));
  } catch {
    return { non_serializable: true };
  }
}

function normalizeRequestMessages(
  messages: ReplayLlmRequestMessage[] | undefined,
): ReplayLlmRequestMessage[] | undefined {
  if (!messages?.length) return undefined;
  return messages.map((message) => ({
    role: message.role,
    content: message.content.slice(0, LLM_MESSAGE_MAX_CHARS),
    ...(message.tool_call_id ? { tool_call_id: message.tool_call_id } : {}),
  }));
}

function normalizeDeltaMessages(
  messages: ReplayPlayerDeltaMessage[] | undefined,
): ReplayPlayerDeltaMessage[] {
  return (messages ?? []).map((message) => ({
    ...message,
    ...(message.content ? { content: message.content.slice(0, LLM_MESSAGE_MAX_CHARS) } : {}),
    ...(message.args !== undefined
      ? { args: safeReplayJson(message.args) as Record<string, unknown> }
      : {}),
    ...(message.result !== undefined
      ? { result: safeReplayJson(message.result) as Record<string, unknown> | string }
      : {}),
  }));
}

/** In-memory aggregate and projection boundary for one replay session. */
export class ReplaySessionAggregate {
  private reproductionEnabled = false;

  enableReproduction(): void {
    this.reproductionEnabled = true;
  }
  private publicSeq = 0;
  private logicSeq = 0;
  private readonly publicEvents: ReplayPublicEvent[] = [];
  private readonly logicOps: ReplayLogicOp[] = [];
  private readonly debugReports: ReplayDebugReport[] = [];
  private readonly playerViews = new Map<number, ReplayPlayerView>();

  constructor(readonly sessionMeta: ReplaySessionMeta) {}

  recordPublicEvent(input: ReplayRecordPublicEventInput): void {
    this.publicEvents.push({
      seq: ++this.publicSeq,
      timestamp: toIso(input.timestampMs),
      phase: input.phase,
      day: input.day,
      ...(input.stage ? { stage: input.stage } : {}),
      type: input.type,
      payload: safeReplayJson(input.payload) as Record<string, unknown>,
    });
  }

  recordLogicOp(input: ReplayRecordLogicOpInput): void {
    this.logicOps.push({
      seq: ++this.logicSeq,
      timestamp: toIso(Date.now()),
      scope: input.scope,
      op: input.op,
      ...(input.eventCount !== undefined ? { event_count: input.eventCount } : {}),
      ...(input.actorId !== undefined ? { actor_id: input.actorId } : {}),
      ...(input.phase ? { phase: input.phase } : {}),
      ...(input.input ? { input: safeReplayJson(input.input) as Record<string, unknown> } : {}),
      ...(input.output ? { output: safeReplayJson(input.output) as Record<string, unknown> } : {}),
      status: input.status,
      ...(input.reason ? { reason: input.reason } : {}),
    });
  }

  recordPlayerRound(input: ReplayRecordPlayerRoundInput): void {
    const view = this.ensurePlayerView(input.playerId, input.role, input.camp);
    if (!view.initial_prompt) {
      view.initial_prompt = {
        day: input.day,
        phase: input.phase,
        stage: input.stage,
        request_id: input.requestId,
        timestamp: toIso(input.timestampMs ?? Date.now()),
        ...(input.initialPromptSystem
          ? { prompt_system: input.initialPromptSystem }
          : input.promptSystem
            ? { prompt_system: input.promptSystem }
            : {}),
        ...(input.initialBoardInfo ? { board_info: input.initialBoardInfo } : {}),
        ...(input.promptUserDelta ? { prompt_user: [...input.promptUserDelta] } : {}),
      };
    }
    const requestMessages = normalizeRequestMessages(input.llmRequestMessages);
    const thinkingText = input.thinkingText?.slice(0, THINKING_MAX_CHARS);
    const deltaMessages = normalizeDeltaMessages(input.deltaMessages);
    if (deltaMessages.length === 0) {
      this.deriveRoundDeltaMessages(deltaMessages, input, requestMessages, thinkingText);
    }
    view.timeline.push({
      seq: view.timeline.length + 1,
      kind: "turn",
      day: input.day,
      phase: input.phase,
      stage: input.stage,
      request_id: input.requestId,
      timestamp: toIso(input.timestampMs ?? Date.now()),
      turn_seq: view.timeline.filter((entry) => entry.kind === "turn").length + 1,
      delta_messages: deltaMessages,
    });
  }

  recordPlayerEvent(input: ReplayRecordPlayerEventInput): void {
    const view = this.ensurePlayerView(input.playerId, input.role, input.camp);
    const entry: ReplayPlayerEventEntry = {
      seq: view.timeline.length + 1,
      kind: "event",
      day: input.day,
      phase: input.phase,
      stage: input.stage,
      request_id: input.requestId,
      timestamp: toIso(input.timestampMs ?? Date.now()),
      ...(input.sourceEventSeq === undefined ? {} : { source_event_seq: input.sourceEventSeq }),
      event: safeReplayJson(input.event) as unknown as PlayerVisibleEvent,
    };
    view.timeline.push(entry);
  }

  recordDebugReport(input: ReplayRecordDebugReportInput): string {
    const reportId = `rb-${this.sessionMeta.sessionId}-${this.debugReports.length + 1}`;
    this.debugReports.push({
      report_id: reportId,
      timestamp: toIso(input.timestampMs ?? Date.now()),
      day: input.day,
      phase: input.phase,
      stage: input.stage,
      actor_id: input.actorId,
      actor_role: input.actorRole,
      actor_camp: input.actorCamp,
      category: input.category,
      severity: input.severity,
      message: input.message,
      evidence_event_seq: [...(input.evidenceEventSeq ?? [])],
      status: "open",
    });
    return reportId;
  }

  publicTimelinePayload() {
    return { events: this.publicEvents };
  }
  logicOpsPayload() {
    return { ops: this.logicOps };
  }
  debugReportsPayload() {
    return {
      session_id: this.sessionMeta.sessionId,
      generated_at: new Date().toISOString(),
      reports: this.debugReports,
    };
  }
  playerIds(): number[] {
    return [...this.playerViews.keys()].sort((a, b) => a - b);
  }
  playerFiles(): string[] {
    return this.playerIds().map((id) => `players/player_${id}.json`);
  }
  normalizedPlayerView(playerId: number): CanonicalReplayPlayerView | undefined {
    const view = this.playerViews.get(playerId);
    return view ? this.normalizePlayerView(view) : undefined;
  }
  normalizedPlayerViews(): CanonicalReplayPlayerView[] {
    return this.playerIds().map((id) => this.normalizedPlayerView(id)!);
  }
  get reproductionOperationCount(): number {
    return this.logicOps.filter((op) => op.scope !== "llm_action_provider").length;
  }
  debugSummaryInput() {
    return {
      reports: this.debugReports,
      publicEvents: this.publicEvents,
      logicOps: this.logicOps,
      playerViews: this.normalizedPlayerViews(),
    };
  }

  buildManifest(meta?: ReplayFinalizeMeta): ReplayManifest {
    const decision =
      meta?.gameResult === undefined
        ? undefined
        : readVictoryResult(
            meta.gameResult,
            meta.players.map((player) => player.player_id),
          );
    if (decision && decision.winner !== meta?.winner)
      throw new Error("replay_result_winner_mismatch");
    return {
      session_id: this.sessionMeta.sessionId,
      board: this.sessionMeta.board,
      ...(this.sessionMeta.locale === undefined ? {} : { locale: this.sessionMeta.locale }),
      ...(this.sessionMeta.random ? { random: this.sessionMeta.random } : {}),
      started_at: this.sessionMeta.startedAtIso,
      ended_at: meta?.endedAtIso ?? this.sessionMeta.startedAtIso,
      winner: meta?.winner ?? null,
      finish_reason: meta?.finishReason ?? "in_progress",
      ...(decision ? { game_result: decision as ReplayManifest["game_result"] } : {}),
      players: meta?.players ?? [],
      files: {
        ...(this.reproductionEnabled ? { reproduction: "reproduction.json" } : {}),
        replay: "replay.json",
        phase_windows: "phase_windows.json",
        timeline_index: "timeline_index.json",
        logic_ops: "logic_ops.json",
        debug_reports: "debug_reports.json",
        debug_summary: "debug_summary.md",
        player_views: this.playerFiles(),
      },
    };
  }

  phaseWindowsPayload(): ReplayPhaseWindowsFile {
    const windows: ReplayPhaseWindow[] = [];
    let current: ReplayPhaseWindow | null = null;
    for (const event of this.publicEvents) {
      const day = Number(event.day);
      const phase = String(event.phase);
      const seq = Number(event.seq);
      const stage = String(event.stage ?? event.type ?? "unknown");
      if (!current || current.day !== day || current.phase !== phase) {
        if (current) windows.push(current);
        current = {
          phase_id: `d${day}-${phase}`,
          day,
          phase,
          start_seq: seq,
          end_seq: seq,
          stages: [{ stage, start_seq: seq, end_seq: seq }],
        };
      } else {
        current.end_seq = seq;
        const last = current.stages.at(-1);
        if (last?.stage === stage) last.end_seq = seq;
        else current.stages.push({ stage, start_seq: seq, end_seq: seq });
      }
    }
    if (current) windows.push(current);
    return { session_id: this.sessionMeta.sessionId, windows };
  }

  timelineIndexPayload(): ReplayTimelineIndexFile {
    const count = this.publicEvents.length;
    const players: ReplayTimelineIndexFile["players"] = {};
    for (const [id, view] of this.playerViews) {
      players[String(id)] = { count: view.timeline.length };
    }
    return {
      session_id: this.sessionMeta.sessionId,
      public: {
        min_seq: count ? this.publicEvents[0].seq : 0,
        max_seq: count ? this.publicEvents.at(-1)!.seq : 0,
        count,
      },
      players,
      phases: { count: this.phaseWindowsPayload().windows.length },
    };
  }

  private ensurePlayerView(playerId: number, role: string, camp: string): ReplayPlayerView {
    const existing = this.playerViews.get(playerId);
    if (existing) return existing;
    const view: ReplayPlayerView = {
      schemaVersion: 2,
      ...(this.sessionMeta.locale === undefined ? {} : { locale: this.sessionMeta.locale }),
      player_id: playerId,
      role,
      camp,
      timeline: [],
    };
    this.playerViews.set(playerId, view);
    return view;
  }

  private normalizePlayerView(view: ReplayPlayerView): CanonicalReplayPlayerView {
    const initialPrompt = view.initial_prompt ?? this.deriveInitialPrompt(view);
    const result: ReplayPlayerView = {
      schemaVersion: 2,
      ...(this.sessionMeta.locale === undefined ? {} : { locale: this.sessionMeta.locale }),
      player_id: view.player_id,
      role: view.role,
      camp: view.camp,
      ...(initialPrompt ? { initial_prompt: initialPrompt } : {}),
      timeline: view.timeline,
    };
    assertReplayPlayerView(result);
    return result;
  }

  private deriveInitialPrompt(
    view: ReplayPlayerView,
  ): ReplayPlayerView["initial_prompt"] | undefined {
    const firstTurn = view.timeline.find((entry) => entry.kind === "turn");
    if (!firstTurn || firstTurn.kind !== "turn") return undefined;
    const system = firstTurn.delta_messages.find(
      (message) => message.role === "system" && message.content,
    );
    return system?.content
      ? {
          day: firstTurn.day,
          phase: firstTurn.phase,
          stage: firstTurn.stage,
          request_id: firstTurn.request_id,
          ...(firstTurn.timestamp ? { timestamp: firstTurn.timestamp } : {}),
          prompt_system: system.content,
        }
      : undefined;
  }

  private deriveRoundDeltaMessages(
    target: ReplayPlayerDeltaMessage[],
    input: ReplayRecordPlayerRoundInput,
    requestMessages: ReplayLlmRequestMessage[] | undefined,
    thinkingText: string | undefined,
  ): void {
    for (const message of requestMessages ?? []) {
      target.push({ role: message.role, kind: "prompt", content: message.content });
    }
    for (const item of input.retryTrace ?? []) {
      if (item.retryPrompt)
        target.push({
          role: "user",
          kind: "retry_prompt",
          attempt: item.attempt,
          content: item.retryPrompt,
        });
      if (item.assistantText)
        target.push({
          role: "assistant",
          kind: "assistant_output",
          attempt: item.attempt,
          content: item.assistantText,
        });
      if (item.reason)
        target.push({
          role: "meta",
          kind: item.status === "request_error" ? "request_error" : "constraint_warning",
          attempt: item.attempt,
          content: item.reason,
          ...(item.diagnostic ? { diagnostic: structuredClone(item.diagnostic) } : {}),
        });
    }
    if (thinkingText)
      target.push({ role: "assistant", kind: "assistant_output", content: thinkingText });
    for (const call of input.toolCalls) {
      target.push({
        role: "assistant",
        kind: "tool_call",
        name: call.name,
        ...(call.args !== undefined
          ? { args: safeReplayJson(call.args) as Record<string, unknown> }
          : {}),
        ...(call.accepted !== undefined ? { accepted: call.accepted } : {}),
      });
      if (call.result !== undefined)
        target.push({
          role: "tool",
          kind: "tool_result",
          name: call.name,
          result: safeReplayJson(call.result) as Record<string, unknown> | string,
        });
    }
    target.push({
      role: "meta",
      kind: "action_summary",
      content: JSON.stringify({
        action_mode: input.actionMode,
        final_action: input.finalAction !== undefined ? safeReplayJson(input.finalAction) : null,
      }),
    });
    if (input.fallback?.used)
      target.push({
        role: "meta",
        kind: "fallback",
        content: JSON.stringify(safeReplayJson(input.fallback)),
      });
  }
}

